package net.minecraft.server; import java.util.*;import java.util.function.*;import net.minecraft.nbt.*;import net.minecraft.world.level.saveddata.*;public class MinecraftServer{public final net.minecraft.server.level.ServerLevel world=new net.minecraft.server.level.ServerLevel(this);public net.minecraft.server.level.ServerLevel overworld(){return world;}public static class Storage{private final Map<String,SavedData> data=new HashMap<>();@SuppressWarnings("unchecked") public <T extends SavedData>T computeIfAbsent(Function<CompoundTag,T> load,Supplier<T> create,String key){return (T)data.computeIfAbsent(key,k->create.get());}}}
